// Build the JSON message envelope that travels through the whole workflow.
const body = $input.first().json.body || $input.first().json;
const text = String(body.text || body.message || '').trim();
if (!text) throw new Error('Empty request: send {"text": "..."}');
if (text.length > 8000) throw new Error('Request too long (max 8000 characters)');
const ov = body.human_override && body.human_override.tier && body.human_override.by ? body.human_override : null;
return [{ json: {
  request_id: 'rr-' + $execution.id + '-' + Date.now().toString(36),
  created_at: new Date().toISOString(),
  channel: body.channel || 'webhook',
  raw_text: text,
  classify_only: body.classify_only === true,
  human_override: ov
}}];

// Lightweight PHI gate for this workflow (irreversible masking before any model sees the text).
// The full reversible Presidio gate lives in the Toxicology Advisor workflow.
const P = [
  ['SSN', /\b\d{3}-\d{2}-\d{4}\b/g],
  ['NATIONAL_ID', /\b[23]\d{13}\b/g],
  ['PHONE', /\b(?:\+?20[ -]?|0)1[0125]\d{8}\b/g],
  ['PHONE', /\b(?:\+?\d{1,3}[ -]?)?\(?\d{3}\)?[ -]?\d{3}[ -]?\d{4}\b/g],
  ['EMAIL', /\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g],
  ['MRN', /\bMRN[:# ]?\s?\d{6,10}\b/gi],
  ['URL', /\bhttps?:\/\/[^\s]+/g],
  ['IP', /\b(?:\d{1,3}\.){3}\d{1,3}\b/g],
];
const it = $input.first().json;
let text = it.raw_text; const counts = {};
for (const [t, re] of P) text = text.replace(re, () => { counts[t] = (counts[t] || 0) + 1; return '[' + t + '_MASKED]'; });
const { raw_text, ...rest } = it;
return [{ json: { ...rest, text, phi_masked: counts } }];

// Deterministic floor for the risk tier. The LLM may raise it, never lower it.
const it = $input.first().json;
const t = it.text;
const R = [
  ['critical', /(suicid|kill (myself|him|her|them)|want to die|end my life|unconscious|unresponsive|not breathing|cardiac arrest|seizure|convuls|anaphyla|respiratory (failure|arrest)|\bcoma\b)/i],
  ['critical', /(انتحار|عايز اموت|عاوز اموت|فاقد الوعي|مش بيتنفس|تشنج|غيبوبة|توقف القلب)/],
  ['high', /(overdose|poison|toxic|ingest|tablets?|pills?|lethal|antidote|pregnan|pediatric|infant|child|newborn|\bdose\b|mg\/kg|warfarin|insulin|digoxin|methotrexate|opioid|chemo)/i],
  ['high', /(جرعة|تسمم|حامل|طفل|رضيع|حبوب|أقراص|اقراص)/],
  ['medium', /(symptom|side effect|interact|treatment|diagnos|medication|prescri|lab result|\bmri\b|ct scan|pain|fever|infection)/i],
  ['medium', /(أعراض|اعراض|دواء|علاج|تحليل|ألم|حرارة|عدوى)/],
];
const order = ['low', 'medium', 'high', 'critical'];
let tier = 'low'; const signals = [];
for (const [lvl, re] of R) { const m = t.match(re); if (m) { signals.push(lvl + ':' + m[0].toLowerCase()); if (order.indexOf(lvl) > order.indexOf(tier)) tier = lvl; } }
return [{ json: { ...it, rule_tier: tier, rule_signals: signals } }];

