// Validate the triage result and fix the final tier.
// Rules: fail-safe-upward; the model can raise the tier but never lower the rule floor; only a human override can lower it.
const order = ['low', 'medium', 'high', 'critical'];
const env = $('Rule-based Pre-Triage').first().json;
let out = $input.first().json.output;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = null; } }
let llmTier = out && typeof out === 'object' ? String(out.risk_tier || '').toLowerCase().trim() : null;
const llmValid = order.includes(llmTier);
const warnings = [];
let tier;
if (!llmValid) { warnings.push('triage_invalid_or_failed -> fail upward to high'); llmTier = null; tier = order[Math.max(order.indexOf(env.rule_tier), order.indexOf('high'))]; }
else tier = order[Math.max(order.indexOf(env.rule_tier), order.indexOf(llmTier))];
let override = null;
if (env.human_override && order.includes(String(env.human_override.tier).toLowerCase())) {
  const req = String(env.human_override.tier).toLowerCase();
  // PATCH: the webhook is unauthenticated, so a caller-supplied override may only RAISE the tier. Lowering is ignored and logged.
  if (order.indexOf(req) > order.indexOf(tier)) { override = { by: env.human_override.by, from: tier, to: req }; tier = req; }
  else warnings.push('human_override_lowering_ignored: requested ' + req + ', kept ' + tier);
}
return [{ json: { ...env, risk_tier: tier, llm_tier: llmTier, llm_rationale: out && out.rationale || null, llm_signals: out && out.signals || [], triage_warnings: warnings, override } }];

// Assemble the final response for the non-human paths.
const env = $('Validate Envelope').first().json;
const paths = [
  ['Low Worker (Local Ollama)', 'local: ollama llama3.2'],
  ['Low Fallback (Gemini Flash-Lite)', 'cloud: gemini-3.5-flash-lite (local model unavailable -> fallback)'],
  ['Medium Worker', 'cloud: gemini-3.5-flash'],
  ['High Worker', 'cloud: gemini-3.5-flash-lite, verified by gemini-3.5-flash-lite'],
];
let used = null;
for (const [n, label] of paths) { try { if ($(n).isExecuted) used = { node: n, label }; } catch (e) {} }
if (!used) throw new Error('No worker output found');
const answer = $(used.node).first().json.output;
let verifier = null;
try { if ($('Verifier Agent').isExecuted) verifier = $('Verifier Agent').first().json.output; } catch (e) {}
return [{ json: {
  request_id: env.request_id, risk_tier: env.risk_tier, rule_tier: env.rule_tier, llm_tier: env.llm_tier,
  signals: env.rule_signals, model_path: used.label, verifier, human_decision: null, override: env.override,
  triage_warnings: env.triage_warnings, created_at: env.created_at,
  response: { request_id: env.request_id, status: 'completed', risk_tier: env.risk_tier, model_path: used.label, verifier, answer,
              disclaimer: 'Decision support for qualified clinicians; not a substitute for clinical judgment.' }
}}];

// Persistent audit trail (workflow static data, last 1000). No request text is stored.
const it = $input.first().json;
const entry = {
  timestamp: new Date().toISOString(), request_id: it.request_id, risk_tier: it.risk_tier, rule_tier: it.rule_tier,
  llm_tier: it.llm_tier, signals: it.signals, model_path: it.model_path,
  verifier_verdict: it.verifier && it.verifier.verdict || null, human_decision: it.human_decision,
  override: it.override || null, warnings: it.triage_warnings || [],
  latency_ms: Date.now() - new Date(it.created_at).getTime()
};
console.log(JSON.stringify(entry));
const sd = $getWorkflowStaticData('global'); sd.routing_audit = sd.routing_audit || [];
sd.routing_audit.push(entry); if (sd.routing_audit.length > 1000) sd.routing_audit.shift();
return [{ json: { ...it, audit: entry } }];

// Collect the draft for human review (critical tier, or the verifier rejected a high-tier draft).
const env = $('Validate Envelope').first().json;
let draft = '', reason = '';
const ok = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
if (ok('Critical Worker')) { draft = $('Critical Worker').first().json.output; reason = 'Critical tier: human approval is mandatory.'; }
else { draft = $('High Worker').first().json.output; const v = $('Verifier Agent').first().json.output || {}; reason = 'Verifier verdict "' + v.verdict + '": ' + (v.issues || []).join('; '); }
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: {
  ...env, draft_html: esc(draft).replace(/\n/g, '<br>'), reason_html: esc(reason), draft_text: draft,
  pending_response: { request_id: env.request_id, status: 'pending_human_approval', risk_tier: env.risk_tier,
    message: 'This request needs human clinician approval before an answer is released.' }
}}];

const env = $('Prepare Approval').first().json;
const approved = $input.first().json.data && $input.first().json.data.approved === true;
const decision = approved ? 'approved' : 'rejected';
return [{ json: {
  request_id: env.request_id, risk_tier: env.risk_tier, rule_tier: env.rule_tier, llm_tier: env.llm_tier, signals: env.rule_signals,
  model_path: 'cloud: gemini-3.5-flash-lite + human approval', verifier: null, human_decision: decision, override: env.override,
  triage_warnings: env.triage_warnings, created_at: env.created_at,
  telegram_text: approved
    ? 'ToxWatch routing ' + env.request_id + ' (' + env.risk_tier + ') APPROVED by human.\n\n' + env.draft_text
    : 'ToxWatch routing ' + env.request_id + ' (' + env.risk_tier + ') BLOCKED by human reviewer. No answer released.'
}}];

// Persistent audit trail (workflow static data, last 1000). No request text is stored.
const it = $input.first().json;
const entry = {
  timestamp: new Date().toISOString(), request_id: it.request_id, risk_tier: it.risk_tier, rule_tier: it.rule_tier,
  llm_tier: it.llm_tier, signals: it.signals, model_path: it.model_path,
  verifier_verdict: it.verifier && it.verifier.verdict || null, human_decision: it.human_decision,
  override: it.override || null, warnings: it.triage_warnings || [],
  latency_ms: Date.now() - new Date(it.created_at).getTime()
};
console.log(JSON.stringify(entry));
const sd = $getWorkflowStaticData('global'); sd.routing_audit = sd.routing_audit || [];
sd.routing_audit.push(entry); if (sd.routing_audit.length > 1000) sd.routing_audit.shift();
return [{ json: { ...it, audit: entry } }];

// Used by the Toxicology Advisor: the caller wants the tier only; medium/high are answered by the full Advisor pipeline.
const env = $input.first().json;
return [{ json: {
  request_id: env.request_id, risk_tier: env.risk_tier, rule_tier: env.rule_tier, llm_tier: env.llm_tier,
  signals: env.rule_signals, model_path: 'classified only -> full Toxicology Advisor pipeline', verifier: null, human_decision: null,
  override: env.override, triage_warnings: env.triage_warnings, created_at: env.created_at,
  response: { request_id: env.request_id, status: 'classified', risk_tier: env.risk_tier, route: 'advisor' }
}}];

// Persistent audit trail (workflow static data, last 1000). No request text is stored.
const it = $input.first().json;
const entry = {
  timestamp: new Date().toISOString(), request_id: it.request_id, risk_tier: it.risk_tier, rule_tier: it.rule_tier,
  llm_tier: it.llm_tier, signals: it.signals, model_path: it.model_path,
  verifier_verdict: it.verifier && it.verifier.verdict || null, human_decision: it.human_decision,
  override: it.override || null, warnings: it.triage_warnings || [],
  latency_ms: Date.now() - new Date(it.created_at).getTime()
};
console.log(JSON.stringify(entry));
const sd = $getWorkflowStaticData('global'); sd.routing_audit = sd.routing_audit || [];
sd.routing_audit.push(entry); if (sd.routing_audit.length > 1000) sd.routing_audit.shift();
return [{ json: { ...it, audit: entry } }];
